<div id="stepText" style="line-height:1.4;color:#222"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ───────── element spec (built exactly as listed) ─────────
   O1,O2             -> SphereGeometry(0.22)                       black
   image plane i     -> PlaneGeometry(4,3) white op.12 + 4 Box borders #333
   epipolar plane    -> BufferGeometry triangle (O1,P,O2)          #FFFF00 op .9 DoubleSide
   pale wedges       -> BufferGeometry triangle (Oi,pi,ei)         #FFFFAA
   rays Oi->P        -> Cylinder tube r .05                        #FF0000
   baseline          -> dashed Cylinder tubes r .045 (dash .35/gap .25) black
   epipolar line i   -> Cylinder tube r .022 clipped to rect       #FF0000
   pink strip i      -> Cylinder tube r .05 (pi -> outer clip end)  #FFB6C1
   p1,p2             -> CircleGeometry .10 + RingGeometry (billboard) red/black
   e1,e2             -> CircleGeometry .10 (billboard)             black
   P                 -> CircleGeometry .13 + ring (billboard)      #66E0E8
   cam-1 axes        -> Cylinder shaft + Cone head                 #00C000
   cam-2 axes        -> Cylinder shaft + Cone head                 #2277FF
   all text          -> addLabel HTML
──────────────────────────────────────────────────────────── */

const UP = new THREE.Vector3(0, 1, 0);
const root = new THREE.Group(); scene.add(root);

const mats = [];
const billboards = [];
const labelRefs = [];

const ORD = { FILL: 1, TRI: 2, WEDGE: 3, PINK: 4, BORDER: 5, LINE: 6, RAY: 7, DOT: 8 };
const C_RED = 0xff0000, C_YEL = 0xffff00, C_PALE = 0xffffaa, C_PINK = 0xffb6c1,
      C_GRN = 0x00c000, C_BLU = 0x2277ff, C_DARK = 0x333333, C_CYAN = 0x66e0e8;

function mkMat(color, opacity, role) {
  const m = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity, depthWrite: false, side: THREE.DoubleSide
  });
  m.userData.base = opacity;
  m.userData.role = role || 'fade';
  mats.push(m);
  return m;
}

function segMesh(parent, color, radius, order, role) {
  const g = new THREE.CylinderGeometry(radius, radius, 1, 12, 1);
  g.translate(0, 0.5, 0);
  const m = new THREE.Mesh(g, mkMat(color, 1, role));
  m.renderOrder = order;
  parent.add(m);
  return m;
}
function setSeg(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (!(len > 1e-6) || !Number.isFinite(len)) { mesh.visible = false; return; }
  mesh.visible = true;
  mesh.position.copy(a);
  mesh.scale.set(1, len, 1);
  mesh.quaternion.setFromUnitVectors(UP, dir.multiplyScalar(1 / len));
}

function triMesh(color, opacity, order, role) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3));
  const m = new THREE.Mesh(g, mkMat(color, opacity, role));
  m.renderOrder = order;
  root.add(m);
  return m;
}
function setTri(mesh, a, b, c) {
  const p = mesh.geometry.attributes.position;
  p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z); p.setXYZ(2, c.x, c.y, c.z);
  p.needsUpdate = true;
  mesh.geometry.computeBoundingBox();
  mesh.geometry.computeBoundingSphere();
}

function mkDot(color, r, role, withRing) {
  const g = new THREE.Group(); root.add(g);
  if (withRing) {
    const ring = new THREE.Mesh(new THREE.RingGeometry(r * 0.95, r * 1.42, 28), mkMat(0x000000, 1, role));
    ring.renderOrder = ORD.DOT; g.add(ring);
  }
  const disc = new THREE.Mesh(new THREE.CircleGeometry(r, 28), mkMat(color, 1, role));
  disc.renderOrder = ORD.DOT + 1;
  disc.position.z = 0.001;
  g.add(disc);
  billboards.push(g);
  return g;
}

function mkArrow(color, role, rad, headR, headL) {
  const g = new THREE.Group(); root.add(g);
  const shaft = segMesh(g, color, rad, ORD.LINE, role);
  const hg = new THREE.ConeGeometry(headR, headL, 16);
  hg.translate(0, headL / 2, 0);
  const head = new THREE.Mesh(hg, mkMat(color, 1, role));
  head.renderOrder = ORD.LINE;
  g.add(head);
  return {
    group: g,
    set(a, dirIn, len) {
      const d = dirIn.clone().normalize();
      const end = a.clone().addScaledVector(d, len);
      setSeg(shaft, a, end.clone().addScaledVector(d, -headL * 0.9));
      head.position.copy(end).addScaledVector(d, -headL);
      head.quaternion.setFromUnitVectors(UP, d);
    }
  };
}

function makePlaneGroup(role) {
  const g = new THREE.Group(); root.add(g);
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(4, 3), mkMat(0xffffff, 0.14, role));
  fill.renderOrder = ORD.FILL; g.add(fill);
  const bw = 0.055;
  const bar = (w, h, x, y) => {
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, bw), mkMat(C_DARK, 1, role));
    b.position.set(x, y, 0); b.renderOrder = ORD.BORDER; g.add(b);
  };
  bar(4 + bw, bw, 0, 1.5); bar(4 + bw, bw, 0, -1.5);
  bar(bw, 3, -2, 0); bar(bw, 3, 2, 0);
  return { group: g, fill };
}

/* ───────── scene objects ───────── */
const pg1 = makePlaneGroup('fade');
const pg2 = makePlaneGroup('keep');

const epiTri = triMesh(C_YEL, 0.9, ORD.TRI, 'fade');
const wedge1 = triMesh(C_PALE, 0.95, ORD.WEDGE, 'fade');
const wedge2 = triMesh(C_PALE, 0.95, ORD.WEDGE, 'keep');

const ray1 = segMesh(root, C_RED, 0.05, ORD.RAY, 'ghost');
const ray2 = segMesh(root, C_RED, 0.05, ORD.RAY, 'keep');

const epiLine1 = segMesh(root, C_RED, 0.022, ORD.RAY, 'fade');
const epiLine2 = segMesh(root, C_RED, 0.022, ORD.RAY, 'keep');
const pink1 = segMesh(root, C_PINK, 0.055, ORD.PINK, 'fade');
const pink2 = segMesh(root, C_PINK, 0.055, ORD.PINK, 'keep');

const baseGrp = new THREE.Group(); root.add(baseGrp);
const dashPool = [];
for (let i = 0; i < 48; i++) {
  const s = segMesh(baseGrp, 0x000000, 0.045, ORD.LINE, 'fade');
  s.visible = false; dashPool.push(s);
