const sBase = document.getElementById('sBase');
const sYaw = document.getElementById('sYaw');
const vBase = document.getElementById('vBase');
const vYaw = document.getElementById('vYaw');
const bRig = document.getElementById('bRig');
const bCam2 = document.getElementById('bCam2');
const bSweep = document.getElementById('bSweep');
const bResetP = document.getElementById('bResetP');
const bPrev = document.getElementById('bPrev');
const bNext = document.getElementById('bNext');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

let tgtBase = state.baseline, tgtYaw = state.yaw;
let sweep = false, sweepT = 0, sweepR = 0, sweepA0 = 0;

