bResetP.addEventListener('click', () => { state.P.copy(P_DEFAULT); setSweep(false); });

let fadeMix = 0, fadeTarget = 0, camAnim = false;
const camGoalPos = new THREE.Vector3(), camGoalLook = new THREE.Vector3();

function setView(mode) {
  state.view = mode;
  bRig.classList.toggle('active', mode === '3D rig');
  bCam2.classList.toggle('active', mode !== '3D rig');
  fadeTarget = (mode === '3D rig') ? 0 : 1;
  camAnim = true;
}
bRig.addEventListener('click', () => setView('3D rig'));
bCam2.addEventListener('click', () => setView('Camera 2 image'));

