const FADE = { keep: 1, ghost: 0.28, fade: 0.07 };
const _pa = new THREE.Vector3(), _pb = new THREE.Vector3();

function screenAngleDeg(a, b) {
  _pa.copy(a).project(camera); _pb.copy(b).project(camera);
  const dx = (_pb.x - _pa.x) * canvas.clientWidth;
  const dy = -(_pb.y - _pa.y) * canvas.clientHeight;
  let ang = Math.atan2(dy, dx) * 180 / Math.PI;
  if (ang > 90) ang -= 180;
  if (ang < -90) ang += 180;
  return ang;
}

function tick() {
  requestAnimationFrame(tick);

  // slider tweens driven by the demo steps
  if (Math.abs(tgtBase - state.baseline) > 0.005) state.baseline += (tgtBase - state.baseline) * 0.12;
  else state.baseline = tgtBase;
  if (Math.abs(tgtYaw - state.yaw) > 0.02) state.yaw += (tgtYaw - state.yaw) * 0.12;
  else state.yaw = tgtYaw;
  sBase.value = state.baseline.toFixed(1);
  sYaw.value = Math.round(state.yaw);
