    controls.target.lerp(camGoalLook, 0.1);
    camera.up.set(0, 1, 0);
    _userMovedCamera = true;
    controls.update();
    if (camera.position.distanceTo(camGoalPos) < 0.04) camAnim = false;
  }
}
