  bar(2 * HW + bw, bw, 0, HH); bar(2 * HW + bw, bw, 0, -HH);
  bar(bw, 2 * HH, -HW, 0); bar(bw, 2 * HH, HW, 0);
  return { group: g, fill };
}

/* ───────── scene objects ───────── */
const pg1 = makePlaneGroup('fade');
const pg2 = makePlaneGroup('keep');

const epiTri = triMesh(C_YEL, 0.9, ORD.TRI, 'fade');
const wedge1 = triMesh(C_PALE, 0.95, ORD.WEDGE, 'fade');
const wedge2 = triMesh(C_PALE, 0.95, ORD.WEDGE, 'keep');

const ray1 = segMesh(root, C_RED, 0.05 * U, ORD.RAY, 'ghost');
const ray2 = segMesh(root, C_RED, 0.05 * U, ORD.RAY, 'keep');

const epiLine1 = segMesh(root, C_RED, 0.022 * U, ORD.RAY, 'fade');
const epiLine2 = segMesh(root, C_RED, 0.022 * U, ORD.RAY, 'keep');
const pink1 = segMesh(root, C_PINK, 0.055 * U, ORD.PINK, 'fade');
const pink2 = segMesh(root, C_PINK, 0.055 * U, ORD.PINK, 'keep');

const baseGrp = new THREE.Group(); root.add(baseGrp);
const dashPool = [];
for (let i = 0; i < 48; i++) {
  const s = segMesh(baseGrp, 0x000000, 0.045 * U, ORD.LINE, 'fade');
  s.visible = false; dashPool.push(s);
}

const sphMat1 = mkMat(0x000000, 1, 'fade');
const sphMat2 = mkMat(0x000000, 1, 'keep');
const o1Mesh = new THREE.Mesh(new THREE.SphereGeometry(0.22 * U, 24, 16), sphMat1);
const o2Mesh = new THREE.Mesh(new THREE.SphereGeometry(0.22 * U, 24, 16), sphMat2);
o1Mesh.renderOrder = ORD.DOT; o2Mesh.renderOrder = ORD.DOT;
root.add(o1Mesh); root.add(o2Mesh);

const e1Dot = mkDot(0x000000, 0.10 * U, 'fade', false);
const e2Dot = mkDot(0x000000, 0.10 * U, 'keep', false);
const p1Dot = mkDot(C_RED, 0.10 * U, 'fade', true);
const p2Dot = mkDot(C_RED, 0.10 * U, 'keep', true);
const pDot  = mkDot(C_CYAN, 0.13 * U, 'fade', true);

const hitSphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.50 * U, 12, 10),
  new THREE.MeshBasicMaterial({ visible: false })
);
pDot.add(hitSphere);

const gUp   = mkArrow(C_GRN, 'fade', 0.032 * U, 0.115 * U, 0.34 * U);
const gDiag = mkArrow(C_GRN, 'fade', 0.032 * U, 0.115 * U, 0.34 * U);
const gAxis = segMesh(root, C_GRN, 0.018 * U, ORD.LINE, 'fade');
gAxis.material.opacity = 0.5; gAxis.material.userData.base = 0.5;

const bUp    = mkArrow(C_BLU, 'keep', 0.030 * U, 0.105 * U, 0.32 * U);
const bRight = mkArrow(C_BLU, 'keep', 0.024 * U, 0.090 * U, 0.28 * U);
const bDown  = mkArrow(C_BLU, 'keep', 0.030 * U, 0.105 * U, 0.32 * U);

/* ───────── state & math ───────── */
const P_DEFAULT = new THREE.Vector3(-0.8 * U, 4.3 * U, -1.2 * U);
const state = {
  baseline: 10,                       // figure units (slider)
  yaw: -12,
  P: P_DEFAULT.clone(),
  view: '3D rig'
};

const O1 = new THREE.Vector3(), O2 = new THREE.Vector3();
const f1 = new THREE.Vector3(), f2 = new THREE.Vector3();
let F1 = null, F2 = null;

const line1A = new THREE.Vector3(), line1B = new THREE.Vector3();
const line2A = new THREE.Vector3(), line2B = new THREE.Vector3();

function makeFrame(O, f) {
  const r = new THREE.Vector3().crossVectors(UP, f).normalize();
  const v = new THREE.Vector3().crossVectors(f, r).normalize();
  const C = O.clone().addScaledVector(f, FOCAL);
  return { O, f, r, v, C };
}
function planeHit(O, X, F) {
  const dv = new THREE.Vector3().subVectors(X, O);
  const den = dv.dot(F.f);
  if (Math.abs(den) < 1e-9) return F.C.clone();
  return O.clone().addScaledVector(dv, FOCAL / den);
}
function toUV(p, F) {
  const q = p.clone().sub(F.C);
  return { u: q.dot(F.r), v: q.dot(F.v) };
}
function fromUV(u, v, F) {
  return F.C.clone().addScaledVector(F.r, u).addScaledVector(F.v, v);
}
function clipRect(eu, ev, du, dv) {
  let s0 = -1e6, s1 = 1e6;
  const tests = [[-du, eu + HW], [du, HW - eu], [-dv, ev + HH], [dv, HH - ev]];
  for (const t of tests) {
    const p = t[0], q = t[1];
    if (Math.abs(p) < 1e-9) { if (q < 0) return null; }
    else {
      const r = q / p;
      if (p < 0) { if (r > s1) return null; if (r > s0) s0 = r; }
      else { if (r < s0) return null; if (r < s1) s1 = r; }
    }
  }
  return [s0, s1];
}
function setDashes(a, b) {
  const L = a.distanceTo(b);
  const dir = b.clone().sub(a).normalize();
  const dash = 0.35 * U, step = 0.60 * U;
  let i = 0, s = 0;
  while (s < L - 0.01 && i < dashPool.length) {
    const e = Math.min(s + dash, L);
    setSeg(dashPool[i], a.clone().addScaledVector(dir, s), a.clone().addScaledVector(dir, e));
    dashPool[i].visible = true;
    i++; s += step;
  }
  for (; i < dashPool.length; i++) dashPool[i].visible = false;
}

/* keep p1 and p2 inside their image rectangles (P is pulled toward the baseline) */
function inRect(p, F, mu, mv) {
  const q = p.clone().sub(F.C);
  return Math.abs(q.dot(F.r)) <= mu * HW && Math.abs(q.dot(F.v)) <= mv * HH;
}
function inFront(O, X, F) { return X.clone().sub(O).dot(F.f) > 1e-6; }
function clampP() {
  const bx = state.P.x, oy = state.P.y, oz = state.P.z;
  const test = (s) => {
    const X = new THREE.Vector3(bx, oy * s, oz * s);
    if (!inFront(O1, X, F1) || !inFront(O2, X, F2)) return false;
    return inRect(planeHit(O1, X, F1), F1, 0.86, 0.84) &&
           inRect(planeHit(O2, X, F2), F2, 0.86, 0.84);
  };
  if (test(1)) return;
  let lo = 0, hi = 1;
  for (let i = 0; i < 16; i++) { const m = (lo + hi) / 2; if (test(m)) lo = m; else hi = m; }
  state.P.y = oy * lo; state.P.z = oz * lo;
  if (state.P.y < 1.0 * U) state.P.y = 1.0 * U;
}

/* ───────── labels (large, serif, white halo — as emphatic as the source) ───────── */
function L(html, role, opts) {
  const e = addLabel(html, new THREE.Vector3(), opts || {});
  e.div.style.fontFamily = "'Times New Roman', Times, Georgia, serif";
  e.div.style.textShadow = '0 0 4px #fff, 0 0 4px #fff, 0 0 3px #fff';
  const rec = { e, role, rot: e.div.querySelector('.rot') };
  labelRefs.push(rec);
  return rec;
}
const lblP     = L('<b>P</b>', 'fade', { fontSize: '22px', offset: [0, -26] });
const lblp1    = L('<b>p</b><sub>1</sub>', 'fade', { fontSize: '20px', offset: [-24, 24] });
const lblp2    = L('<b>p</b><sub>2</sub>', 'keep', { fontSize: '20px', offset: [26, 26] });
const lblO1    = L('O<sub>1</sub>', 'fade', { fontSize: '20px', offset: [-4, 34] });
const lblO2    = L('O<sub>2</sub>', 'keep', { fontSize: '20px', offset: [4, 34] });
const lble1    = L('e<sub>1</sub>', 'fade', { fontSize: '18px', offset: [6, 26] });
const lble2    = L('e<sub>2</sub>', 'keep', { fontSize: '18px', offset: [6, 26] });
const lblCam1  = L('Camera 1', 'fade', { fontSize: '19px' });
const lblCam2  = L('Camera 2', 'keep', { fontSize: '19px' });
const lblPlane = L('Epipolar plane', 'fade', { fontSize: '20px' });
const lblLn1   = L('<span class="rot" style="display:inline-block">Epipolar line</span>', 'fade', { fontSize: '15px', offset: [0, -12] });
const lblLn2   = L('<span class="rot" style="display:inline-block">Epipolar line</span>', 'keep', { fontSize: '15px', offset: [0, -12] });

/* ───────── per-frame rebuild of every derived quantity ───────── */
function update() {
  const half = state.baseline * U / 2;
  O1.set(-half, 0, 0);
  O2.set(half, 0, 0);
  f1.set(1, 0, -0.12).normalize();
  f2.set(-1, 0, -0.12).normalize().applyAxisAngle(UP, THREE.MathUtils.degToRad(state.yaw));
  F1 = makeFrame(O1, f1);
  F2 = makeFrame(O2, f2);

  clampP();

  pg1.group.position.copy(F1.C);
  pg1.group.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(F1.r, F1.v, F1.f));
  pg2.group.position.copy(F2.C);
  pg2.group.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(F2.r, F2.v, F2.f));

  const e1 = planeHit(O1, O2, F1);
  const e2 = planeHit(O2, O1, F2);
  const p1 = planeHit(O1, state.P, F1);
  const p2 = planeHit(O2, state.P, F2);

  setTri(epiTri, O1, state.P, O2);
  setTri(wedge1, O1, p1, e1);
  setTri(wedge2, O2, p2, e2);

  setSeg(ray1, O1, state.P);
  setSeg(ray2, O2, state.P);

  setDashes(O1, O2);

  function buildLine(F, e, p, lineMesh, pinkMesh, outA, outB) {
    const E = toUV(e, F), Q = toUV(p, F);
    let du = Q.u - E.u, dv = Q.v - E.v;
    const n = Math.hypot(du, dv);
    if (n < 1e-7) { du = 0.9; dv = 0.45; } else { du /= n; dv /= n; }
    const s = clipRect(E.u, E.v, du, dv);
    if (!s) { lineMesh.visible = false; pinkMesh.visible = false; return; }
    const A = fromUV(E.u + du * s[0], E.v + dv * s[0], F);
    const B = fromUV(E.u + du * s[1], E.v + dv * s[1], F);
    setSeg(lineMesh, A, B);
    const away = (B.clone().sub(p).dot(p.clone().sub(e)) > 0) ? B : A;
    setSeg(pinkMesh, p, away);
    outA.copy(p); outB.copy(away);
  }
  buildLine(F1, e1, p1, epiLine1, pink1, line1A, line1B);
  buildLine(F2, e2, p2, epiLine2, pink2, line2A, line2B);

  o1Mesh.position.copy(O1);
  o2Mesh.position.copy(O2);
  e1Dot.position.copy(e1);
  e2Dot.position.copy(e2);
  p1Dot.position.copy(p1);
  p2Dot.position.copy(p2);
  pDot.position.copy(state.P);

  gUp.set(e1.clone().addScaledVector(F1.v, -1.55 * U), F1.v, 3.0 * U);
  gDiag.set(e1.clone(), F1.r.clone().negate().addScaledVector(F1.v, 0.45), 2.1 * U);
  setSeg(gAxis, O1, e1.clone().addScaledVector(F1.f, 0.7 * U));

  bUp.set(e2.clone().addScaledVector(F2.v, -1.4 * U), F2.v, 3.0 * U);
  bRight.set(e2.clone(), F2.r.clone().negate().addScaledVector(F2.v, 0.25), 2.4 * U);
  bDown.set(e2.clone(), F2.r.clone().addScaledVector(F2.v, -0.55), 1.25 * U);

  lblP.e.pos.copy(state.P);
  lblp1.e.pos.copy(p1);
  lblp2.e.pos.copy(p2);
  lblO1.e.pos.copy(O1);
  lblO2.e.pos.copy(O2);
  lble1.e.pos.copy(e1);
  lble2.e.pos.copy(e2);
  lblCam1.e.pos.copy(O1).add(new THREE.Vector3(-1.55 * U, 0.65 * U, 0));
  lblCam2.e.pos.copy(O2).add(new THREE.Vector3(1.55 * U, 0.95 * U, 0));
  lblPlane.e.pos.copy(O1).add(state.P).add(O2).multiplyScalar(1 / 3).addScaledVector(UP, 0.85 * U);
  lblLn1.e.pos.copy(line1A).lerp(line1B, 0.66);
  lblLn2.e.pos.copy(line2A).lerp(line2B, 0.66);
}
update();

/* ───────── camera framing (after all geometry exists) ───────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 60,        // 30° off frontal: image planes read as real parallelograms
  elevationDeg: 12,
  rollDeg: 0,
  heightFraction: 0.8
});

/* ───────── hover/click explainers ───────── */
registerInteractive(epiTri, {
  title: 'Epipolar plane',
  tooltip: 'Epipolar plane O₁–P–O₂',
  body: 'The triangle through the two camera centres and the scene point P. Its intersection with each image plane is that image\'s epipolar line.'
});
registerInteractive(baseGrp, {
  title: 'Baseline O₁O₂',
  tooltip: 'Baseline — pierces each image plane at an epipole',
  body: 'The segment joining the camera centres. Where it pierces image i you get the epipole eᵢ, through which every epipolar line of that image passes.'
});
registerInteractive(pg2.fill, {
  title: 'Image plane 2',
  tooltip: 'Image plane of camera 2',
  body: 'If p₁ is known, the matching point p₂ must lie on the red epipolar line in this plane — a 1-D search instead of a 2-D one.'
});
registerInteractive(pg1.fill, {
  title: 'Image plane 1',
  tooltip: 'Image plane of camera 1',
  body: 'The ray O₁P pierces this rectangle at p₁. Every scene point along that ray gives the same p₁ — depth is what stereo must recover.'
});

/* ───────── UI wiring ───────── */
const sBase = document.getElementById('sBase');
const sYaw = document.getElementById('sYaw');
const vBase = document.getElementById('vBase');
const vYaw = document.getElementById('vYaw');
const bRig = document.getElementById('bRig');
const bCam2 = document.getElementById('bCam2');
const bSweep = document.getElementById('bSweep');
const bResetP = document.getElementById('bResetP');
const bPrev = document.getElementById('bPrev');
const bNext = document.getElementById('bNext');
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');

let tgtBase = state.baseline, tgtYaw = state.yaw;
let sweep = false, sweepT = 0, sweepR = 0, sweepA0 = 0;

sBase.addEventListener('input', () => { tgtBase = parseFloat(sBase.value); state.baseline = tgtBase; });
sYaw.addEventListener('input', () => { tgtYaw = parseFloat(sYaw.value); state.yaw = tgtYaw; });

function setSweep(on) {
  sweep = on;
  bSweep.classList.toggle('active', on);
  if (on) {
    sweepR = Math.hypot(state.P.y, state.P.z) || 4.4 * U;
    sweepA0 = Math.atan2(state.P.z, state.P.y);
    sweepT = 0;
  }
}
bSweep.addEventListener('click', () => setSweep(!sweep));
bResetP.addEventListener('click', () => { state.P.copy(P_DEFAULT); setSweep(false); });

let fadeMix = 0, fadeTarget = 0, camAnim = false;
const camGoalPos = new THREE.Vector3(), camGoalLook = new THREE.Vector3();

function setView(mode) {
  state.view = mode;
  bRig.classList.toggle('active', mode === '3D rig');
  bCam2.classList.toggle('active', mode !== '3D rig');
  fadeTarget = (mode === '3D rig') ? 0 : 1;
  camAnim = true;
}
bRig.addEventListener('click', () => setView('3D rig'));
bCam2.addEventListener('click', () => setView('Camera 2 image'));

/* ───────── demo steps ───────── */
const STEPS = [
  { title: 'The rig and the baseline',
    narration: 'Two camera centres O₁ and O₂ are joined by the dashed baseline, which pierces each image plane at the epipoles e₁ and e₂. Everything else is built from these five points.',
    st: { view: '3D rig', baseline: 10, yaw: -12, sweep: false } },
  { title: 'One point, one plane',
    narration: 'The scene point P closes the triangle O₁–P–O₂: that yellow triangle is the epipolar plane, and the red rays O₁P and O₂P pierce the image planes at p₁ and p₂.',
    st: { view: '3D rig', baseline: 10, yaw: -12, sweep: false } },
  { title: 'Sweeping P about the baseline',
    narration: 'The epipolar plane rotates around the fixed baseline like a page in a book, so p₁ and p₂ slide but each stays on its epipolar line through its epipole. Drag P yourself to explore.',
    st: { view: '3D rig', baseline: 10, yaw: -12, sweep: true } },
  { title: 'Only relative pose matters',
    narration: 'Widen the baseline and rotate camera 2. The epipoles migrate and the epipolar lines fan to new orientations — the constraint is set by camera geometry alone.',
    st: { view: '3D rig', baseline: 13, yaw: 28, sweep: false } },
  { title: '2D search becomes 1D',
    narration: 'Looking straight into camera 2\'s image, the match for p₁ must lie on a single red line — which is why stereo matching is a one-dimensional search.',
    st: { view: 'Camera 2 image', baseline: 10, yaw: -12, sweep: false } }
];
let step = 0;
function goToStep(i) {
  step = (i % STEPS.length + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  tgtBase = s.st.baseline;
  tgtYaw = s.st.yaw;
  setView(s.st.view);
  if (s.st.sweep) { state.P.copy(P_DEFAULT); setSweep(true); } else setSweep(false);
  stepTitle.textContent = (step + 1) + '/' + STEPS.length + '. ' + s.title;
  stepText.textContent = s.narration;
}
bPrev.addEventListener('click', () => goToStep(step - 1));
bNext.addEventListener('click', () => goToStep(step + 1));
goToStep(0);

/* ───────── drag P ───────── */
const rc = new THREE.Raycaster();
const dragPlane = new THREE.Plane();
const hitPt = new THREE.Vector3();
let dragging = false;

function ptrNDC(ev) {
  const r = canvas.getBoundingClientRect();
  return new THREE.Vector2(
    ((ev.clientX - r.left) / r.width) * 2 - 1,
    -((ev.clientY - r.top) / r.height) * 2 + 1
  );
}
canvas.addEventListener('pointerdown', (ev) => {
  rc.setFromCamera(ptrNDC(ev), camera);
  if (rc.intersectObject(pDot, true).length) {
    dragging = true;
    setSweep(false);
    controls.enabled = false;
    canvas.setPointerCapture && canvas.setPointerCapture(ev.pointerId);
  }
});
canvas.addEventListener('pointermove', (ev) => {
  if (!dragging) {
    rc.setFromCamera(ptrNDC(ev), camera);
    if (rc.intersectObject(pDot, true).length) canvas.style.cursor = 'move';
    return;
  }
  const n = ev.shiftKey ? UP.clone()
    : camera.getWorldDirection(new THREE.Vector3()).negate();
  dragPlane.setFromNormalAndCoplanarPoint(n, state.P);
  rc.setFromCamera(ptrNDC(ev), camera);
  if (rc.ray.intersectPlane(dragPlane, hitPt)) {
    const half = state.baseline * U / 2;
    state.P.set(
      THREE.MathUtils.clamp(hitPt.x, -half * 0.96, half * 0.96),
      THREE.MathUtils.clamp(hitPt.y, 1.0 * U, 7.0 * U),
      THREE.MathUtils.clamp(hitPt.z, -5.0 * U, 4.0 * U)
    );
  }
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; canvas.style.cursor = 'default'; }
});

/* ───────── per-frame loop: tweens, billboards, label rotation, fades ───────── */
const FADE = { keep: 1, ghost: 0.28, fade: 0.07 };
const _pa = new THREE.Vector3(), _pb = new THREE.Vector3();

function screenAngleDeg(a, b) {
  _pa.copy(a).project(camera); _pb.copy(b).project(camera);
  const dx = (_pb.x - _pa.x) * canvas.clientWidth;
  const dy = -(_pb.y - _pa.y) * canvas.clientHeight;
  let ang = Math.atan2(dy, dx) * 180 / Math.PI;
  if (ang > 90) ang -= 180;
  if (ang < -90) ang += 180;
  return ang;
}

function tick() {
  requestAnimationFrame(tick);

  if (Math.abs(tgtBase - state.baseline) > 0.005) state.baseline += (tgtBase - state.baseline) * 0.12;
  else state.baseline = tgtBase;
  if (Math.abs(tgtYaw - state.yaw) > 0.02) state.yaw += (tgtYaw - state.yaw) * 0.12;
  else state.yaw = tgtYaw;
  sBase.value = state.baseline.toFixed(1);
  sYaw.value = Math.round(state.yaw);
  vBase.textContent = state.baseline.toFixed(1);
  vYaw.textContent = Math.round(state.yaw);

  if (sweep) {
    sweepT += 0.012;
    const a = sweepA0 + 0.55 * Math.sin(sweepT);
    state.P.y = sweepR * Math.cos(a);
    state.P.z = sweepR * Math.sin(a);
    if (state.P.y < 1.0 * U) state.P.y = 1.0 * U;
  }

  update();

  for (const b of billboards) b.quaternion.copy(camera.quaternion);

  if (lblLn1.rot) lblLn1.rot.style.transform = 'rotate(' + screenAngleDeg(line1A, line1B).toFixed(1) + 'deg)';
  if (lblLn2.rot) lblLn2.rot.style.transform = 'rotate(' + screenAngleDeg(line2A, line2B).toFixed(1) + 'deg)';

  fadeMix += (fadeTarget - fadeMix) * 0.09;
  for (const m of mats) {
    const lvl = FADE[m.userData.role] !== undefined ? FADE[m.userData.role] : FADE.fade;
    m.opacity = m.userData.base * (1 + (lvl - 1) * fadeMix);
  }
  for (const r of labelRefs) {
    const lvl = FADE[r.role] !== undefined ? FADE[r.role] : FADE.fade;
    r.e.div.style.opacity = (1 + (lvl - 1) * fadeMix).toFixed(3);
  }

  if (camAnim) {
    if (state.view === '3D rig') {
      camGoalPos.copy(HOME_POS); camGoalLook.copy(HOME_TARGET);
    } else {
      camGoalPos.copy(O2).addScaledVector(f2, -2.35).addScaledVector(UP, 0.04);
      camGoalLook.copy(F2.C);
    }
    camera.position.lerp(camGoalPos, 0.1);
    controls.target.lerp(camGoalLook, 0.1);
    camera.up.set(0, 1, 0);
    _userMovedCamera = true;
    controls.update();
    if (camera.position.distanceTo(camGoalPos) < 0.01) camAnim = false;
  }
}
tick();
// @FIGURE_CODE_END

