<!-- @FIGURE_UI_BEGIN -->
<div style="font-weight:700;font-size:13px;margin-bottom:2px">Epipolar geometry of a stereo pair</div>
<div style="font-size:11px;color:#444;line-height:1.35;margin-bottom:4px">
  Drag the cyan point <b>P</b> in the figure (hold <b>Shift</b> to move it in depth). Drag empty space to orbit the rig.
</div>

<label>Baseline |O<sub>1</sub>O<sub>2</sub>| = <span id="vBase">10.0</span>
