<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── element spec (figure units × U) ─────────────────────────────────────────
   O1,O2            -> SphereGeometry(0.22U)                       black
   image plane i    -> PlaneGeometry(8.0U x 3.6U) white op.13 + 4 Box borders #333
   epipolar plane   -> BufferGeometry triangle (O1,P,O2)  #FFFF00 op.9 DoubleSide
   pale wedges      -> BufferGeometry triangle (Oi,pi,ei) #FFFFAA
   rays Oi->P       -> Cylinder tube r .05U                        #FF0000
   baseline         -> dashed Cylinder tubes r .045U (dash .35U / step .60U) black
   epipolar line i  -> Cylinder tube r .022U clipped to rect       #FF0000
   pink strip i     -> Cylinder tube r .055U (pi -> outer clip end) #FFB6C1
   p1,p2            -> CircleGeometry .10U + RingGeometry (billboard) red/black
   e1,e2            -> CircleGeometry .10U (billboard)             black
   P                -> CircleGeometry .13U + ring (billboard)      #66E0E8
   cam-1 axes       -> Cylinder shaft + Cone head                  #00C000
   cam-2 axes       -> Cylinder shaft + Cone head                  #2277FF
   all text         -> addLabel HTML, serif, white halo
─────────────────────────────────────────────────────────────────────────────*/

const U = 0.30;                                 // world units per figure unit
const UP = new THREE.Vector3(0, 1, 0);
const dom = renderer.domElement;
const root = new THREE.Group(); scene.add(root);

const mats = [];
const billboards = [];
const labelRefs = [];

const ORD = { FILL: 1, TRI: 2, WEDGE: 3, PINK: 4, BORDER: 5, LINE: 6, RAY: 7, DOT: 8 };
const C_RED = 0xff0000, C_YEL = 0xffff00, C_PALE = 0xffffaa, C_PINK = 0xffb6c1,
      C_GRN = 0x00c000, C_BLU = 0x2277ff, C_DARK = 0x333333, C_CYAN = 0x66e0e8;

const HW = 4.0 * U, HH = 1.8 * U, FOCAL = 1.9 * U;   // image rect half sizes, focal
const PU0 = 1.4 * U, PV0 = 0.50 * U;                 // principal-point offsets

/* ── helpers ─────────────────────────────────────────────────────────────── */
function mkMat(color, opacity, role) {
  const m = new THREE.MeshBasicMaterial({
    color, transparent: true, opacity, depthWrite: false, side: THREE.DoubleSide
  });
  m.userData.base = opacity;
  m.userData.role = role || 'fade';
  mats.push(m);
  return m;
}

function segMesh(parent, color, radius, order, role) {
  const g = new THREE.CylinderGeometry(radius, radius, 1, 12, 1);
  g.translate(0, 0.5, 0);
  const m = new THREE.Mesh(g, mkMat(color, 1, role));
  m.renderOrder = order;
  parent.add(m);
  return m;
}
function setSeg(mesh, a, b) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  if (!(len > 1e-7) || !Number.isFinite(len)) { mesh.visible = false; return; }
  mesh.visible = true;
  mesh.position.copy(a);
  mesh.scale.set(1, len, 1);
  mesh.quaternion.setFromUnitVectors(UP, dir.multiplyScalar(1 / len));
}

function triMesh(color, opacity, order, role) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(9), 3));
  const m = new THREE.Mesh(g, mkMat(color, opacity, role));
  m.renderOrder = order;
  root.add(m);
  return m;
}
function setTri(mesh, a, b, c) {
  const p = mesh.geometry.attributes.position;
  p.setXYZ(0, a.x, a.y, a.z); p.setXYZ(1, b.x, b.y, b.z); p.setXYZ(2, c.x, c.y, c.z);
  p.needsUpdate = true;
  mesh.geometry.computeBoundingBox();
  mesh.geometry.computeBoundingSphere();
}

function mkDot(color, r, role, withRing) {
  const g = new THREE.Group(); root.add(g);
  if (withRing) {
    const ring = new THREE.Mesh(new THREE.RingGeometry(r * 0.95, r * 1.5, 28), mkMat(0x000000, 1, role));
    ring.renderOrder = ORD.DOT;
    g.add(ring);
  }
  const disc = new THREE.Mesh(new THREE.CircleGeometry(r, 28), mkMat(color, 1, role));
  disc.renderOrder = ORD.DOT + 1;
  disc.position.z = 0.0006;
  g.add(disc);
  billboards.push(g);
  return g;
}

function mkArrow(color, role, rad, headR, headL) {
  const g = new THREE.Group(); root.add(g);
  const shaft = segMesh(g, color, rad, ORD.LINE, role);
  const hg = new THREE.ConeGeometry(headR, headL, 16);
  hg.translate(0, headL / 2, 0);
  const head = new THREE.Mesh(hg, mkMat(color, 1, role));
  head.renderOrder = ORD.LINE;
  g.add(head);
  return {
    group: g,
    set(a, dirIn, len) {
      const dd = dirIn.clone().normalize();
      const end = a.clone().addScaledVector(dd, len);
      setSeg(shaft, a, end.clone().addScaledVector(dd, -headL * 0.9));
      head.position.copy(end).addScaledVector(dd, -headL);
      head.quaternion.setFromUnitVectors(UP, dd);
    }
  };
}

function makePlaneGroup(role) {
  const g = new THREE.Group(); root.add(g);
  const fill = new THREE.Mesh(new THREE.PlaneGeometry(2 * HW, 2 * HH), mkMat(0xffffff, 0.13, role));
  fill.renderOrder = ORD.FILL;
  g.add(fill);
  const bw = 0.06 * U;
  const bar = (w, h, x, y) => {
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, bw), mkMat(C_DARK, 1, role));
    b.position.set(x, y, 0);
    b.renderOrder = ORD.BORDER;
    g.add(b);
  };
  bar(2 * HW + bw, bw, 0, HH);
  bar(2 * HW + bw, bw, 0, -HH);
  bar(bw, 2 * HH, -HW, 0);
  bar(bw, 2 * HH, HW, 0);
  return { group: g, fill };
}

/* ── scene objects ───────────────────────────────────────────────────────── */
const pg1 = makePlaneGroup('fade');
const pg2 = makePlaneGroup('keep');

const epiTri = triMesh(C_YEL, 0.9, ORD.TRI, 'fade');
const wedge1 = triMesh(C_PALE, 0.95, ORD.WEDGE, 'fade');
const wedge2 = triMesh(C_PALE, 0.95, ORD.WEDGE, 'keep');

const ray1 = segMesh(root, C_RED, 0.05 * U, ORD.RAY, 'ghost');
const ray2 = segMesh(root, C_RED, 0.05 * U, ORD.RAY, 'ghost');

const epiLine1 = segMesh(root, C_RED, 0.022 * U, ORD.RAY, 'fade');
const epiLine2 = segMesh(root, C_RED, 0.022 * U, ORD.RAY, 'keep');
const pink1 = segMesh(root, C_PINK, 0.055 * U, ORD.PINK, 'fade');
const pink2 = segMesh(root, C_PINK, 0.055 * U, ORD.PINK, 'keep');

const baseGrp = new THREE.Group(); root.add(baseGrp);
const dashPool = [];
for (let i = 0; i < 56; i++) {
  const s = segMesh(baseGrp, 0x000000, 0.045 * U, ORD.LINE, 'fade');
  s.visible = false;
  dashPool.push(s);
}

const o1Mesh = new THREE.Mesh(new THREE.SphereGeometry(0.22 * U, 24, 16), mkMat(0x000000, 1, 'fade'));
const o2Mesh = new THREE.Mesh(new THREE.SphereGeometry(0.22 * U, 24, 16), mkMat(0x000000, 1, 'ghost'));
o1Mesh.renderOrder = ORD.DOT; o2Mesh.renderOrder = ORD.DOT;
root.add(o1Mesh); root.add(o2Mesh);

const e1Dot = mkDot(0x000000, 0.10 * U, 'fade', false);
const e2Dot = mkDot(0x000000, 0.10 * U, 'keep', false);
const p1Dot = mkDot(C_RED, 0.10 * U, 'fade', true);
const p2Dot = mkDot(C_RED, 0.10 * U, 'keep', true);
const pDot  = mkDot(C_CYAN, 0.13 * U, 'fade', true);

const hitSphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.55 * U, 12, 10),
  new THREE.MeshBasicMaterial({ visible: false })
);
pDot.add(hitSphere);

const gUp   = mkArrow(C_GRN, 'fade', 0.032 * U, 0.115 * U, 0.34 * U);
const gDiag = mkArrow(C_GRN, 'fade', 0.032 * U, 0.115 * U, 0.34 * U);
const gAxis = segMesh(root, C_GRN, 0.018 * U, ORD.LINE, 'fade');
gAxis.material.opacity = 0.5; gAxis.material.userData.base = 0.5;

const bUp    = mkArrow(C_BLU, 'keep', 0.030 * U, 0.105 * U, 0.32 * U);
const bRight = mkArrow(C_BLU, 'keep', 0.024 * U, 0.090 * U, 0.28 * U);
const bDown  = mkArrow(C_BLU, 'keep', 0.030 * U, 0.105 * U, 0.32 * U);

/* ── state & projective math ─────────────────────────────────────────────── */
const P_DEFAULT = new THREE.Vector3(-0.6 * U, 4.4 * U, -1.4 * U);
const state = { baseline: 10, yaw: -12, P: P_DEFAULT.clone(), view: '3D rig' };

const O1 = new THREE.Vector3(), O2 = new THREE.Vector3();
const f1 = new THREE.Vector3(), f2 = new THREE.Vector3();
let F1 = null, F2 = null;
const line1A = new THREE.Vector3(), line1B = new THREE.Vector3();
const line2A = new THREE.Vector3(), line2B = new THREE.Vector3();
const E1 = new THREE.Vector3(), E2 = new THREE.Vector3();
const P1 = new THREE.Vector3(), P2 = new THREE.Vector3();

function makeFrame(O, f) {
  const r = new THREE.Vector3().crossVectors(UP, f).normalize();
  const v = new THREE.Vector3().crossVectors(f, r).normalize();
  const C = O.clone().addScaledVector(f, FOCAL).addScaledVector(r, PU0).addScaledVector(v, PV0);
  return { O, f, r, v, C };
}
function planeHit(O, X, F) {
  const dv = new THREE.Vector3().subVectors(X, O);
  const den = dv.dot(F.f);
  if (Math.abs(den) < 1e-9) return F.C.clone();
  return O.clone().addScaledVector(dv, FOCAL / den);
}
function toUV(p, F) {
  const q = p.clone().sub(F.C);
  return { u: q.dot(F.r), v: q.dot(F.v) };
}
function fromUV(u, v, F) {
  return F.C.clone().addScaledVector(F.r, u).addScaledVector(F.v, v);
}
function clipRect(eu, ev, du, dv) {                 // Liang–Barsky in (u,v)
  let s0 = -1e6, s1 = 1e6;
  const tests = [[-du, eu + HW], [du, HW - eu], [-dv, ev + HH], [dv, HH - ev]];
  for (const t of tests) {
    const p = t[0], q = t[1];
    if (Math.abs(p) < 1e-9) { if (q < 0) return null; }
    else {
      const r = q / p;
      if (p < 0) { if (r > s1) return null; if (r > s0) s0 = r; }
      else { if (r < s0) return null; if (r < s1) s1 = r; }
    }
  }
  return [s0, s1];
}
function setDashes(a, b) {
  const L = a.distanceTo(b);
  const dir = b.clone().sub(a).normalize();
  const dash = 0.35 * U, step = 0.60 * U;
  let i = 0, s = 0;
  while (s < L - 0.01 && i < dashPool.length) {
    const e = Math.min(s + dash, L);
    setSeg(dashPool[i], a.clone().addScaledVector(dir, s), a.clone().addScaledVector(dir, e));
    dashPool[i].visible = true;
    i++; s += step;
  }
  for (; i < dashPool.length; i++) dashPool[i].visible = false;
}
function inRect(p, F, mu, mv) {
  const q = p.clone().sub(F.C);
  return Math.abs(q.dot(F.r)) <= mu * HW && Math.abs(q.dot(F.v)) <= mv * HH;
}
function inFront(O, X, F) { return X.clone().sub(O).dot(F.f) > 1e-6; }
function clampP() {                                 // keep p1,p2 inside both images
  const bx = state.P.x, oy = state.P.y, oz = state.P.z;
  const test = (s) => {
    const X = new THREE.Vector3(bx, oy * s, oz * s);
    if (!inFront(O1, X, F1) || !inFront(O2, X, F2)) return false;
    return inRect(planeHit(O1, X, F1), F1, 0.9, 0.86) &&
           inRect(planeHit(O2, X, F2), F2, 0.9, 0.86);
  };
  if (test(1)) return;
  let lo = 0, hi = 1;
  for (let i = 0; i < 18; i++) { const m = (lo + hi) / 2; if (test(m)) lo = m; else hi = m; }
  state.P.y = oy * lo; state.P.z = oz * lo;
  if (state.P.y < 1.2 * U) state.P.y = 1.2 * U;
}

/* ── geometry rebuild (every frame, nothing hard-coded) ──────────────────── */
function update() {
  const half = state.baseline * U / 2;
  O1.set(-half, 0, 0);
  O2.set(half, 0, 0);
  f1.set(1, 0, -0.12).normalize();
  f2.set(-1, 0, -0.12).normalize().applyAxisAngle(UP, THREE.MathUtils.degToRad(state.yaw));
  F1 = makeFrame(O1, f1);
  F2 = makeFrame(O2, f2);

  clampP();

  pg1.group.position.copy(F1.C);
  pg1.group.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(F1.r, F1.v, F1.f));
  pg2.group.position.copy(F2.C);
  pg2.group.quaternion.setFromRotationMatrix(new THREE.Matrix4().makeBasis(F2.r, F2.v, F2.f));

  E1.copy(planeHit(O1, O2, F1));
  E2.copy(planeHit(O2, O1, F2));
  P1.copy(planeHit(O1, state.P, F1));
  P2.copy(planeHit(O2, state.P, F2));

  setTri(epiTri, O1, state.P, O2);
  setTri(wedge1, O1, P1, E1);
  setTri(wedge2, O2, P2, E2);

  setSeg(ray1, O1, state.P);
  setSeg(ray2, O2, state.P);
  setDashes(O1, O2);

  function buildLine(F, e, p, lineMesh, pinkMesh, outA, outB) {
    const Eu = toUV(e, F), Qu = toUV(p, F);
    let du = Qu.u - Eu.u, dv = Qu.v - Eu.v;
    const n = Math.hypot(du, dv);
    if (n < 1e-7) { du = 0.9; dv = 0.45; } else { du /= n; dv /= n; }
    const s = clipRect(Eu.u, Eu.v, du, dv);
    if (!s) { lineMesh.visible = false; pinkMesh.visible = false; return; }
    const A = fromUV(Eu.u + du * s[0], Eu.v + dv * s[0], F);
    const B = fromUV(Eu.u + du * s[1], Eu.v + dv * s[1], F);
    setSeg(lineMesh, A, B);
    const away = (B.clone().sub(p).dot(p.clone().sub(e)) > 0) ? B : A;
    setSeg(pinkMesh, p, away);
    outA.copy(p); outB.copy(away);
  }
  buildLine(F1, E1, P1, epiLine1, pink1, line1A, line1B);
  buildLine(F2, E2, P2, epiLine2, pink2, line2A, line2B);

  o1Mesh.position.copy(O1);
  o2Mesh.position.copy(O2);
  e1Dot.position.copy(E1);
  e2Dot.position.copy(E2);
  p1Dot.position.copy(P1);
  p2Dot.position.copy(P2);
  pDot.position.copy(state.P);

  gUp.set(E1.clone().addScaledVector(F1.v, -1.4 * U), F1.v, 3.0 * U);
  gDiag.set(E1.clone(), F1.r.clone().negate().addScaledVector(F1.v, 0.5), 2.1 * U);
  setSeg(gAxis, O1, E1.clone());

  bUp.set(E2.clone().addScaledVector(F2.v, -1.3 * U), F2.v, 3.0 * U);
  bRight.set(E2.clone(), F2.r.clone().negate().addScaledVector(F2.v, 0.25), 2.3 * U);
  bDown.set(E2.clone(), F2.r.clone().addScaledVector(F2.v, -0.55), 1.2 * U);
}
update();

/* ── camera framing (all geometry exists) ────────────────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 105,      // 15° past frontal, as measured off the source
  elevationDeg: 13,
  rollDeg: 0,
  heightFraction: 0.62
});
const homePos = camera.position.clone();
const homeTarget = controls.target.clone();

/* ── labels ──────────────────────────────────────────────────────────────── */
function L(html, role, opts) {
  const e = addLabel(html, new THREE.Vector3(), opts || {});
  e.div.style.fontFamily = "'Times New Roman', Times, Georgia, serif";
  e.div.style.textShadow = '0 0 4px #fff, 0 0 4px #fff, 0 0 3px #fff';
  const rec = { e, role, rot: e.div.querySelector('.rot') };
  labelRefs.push(rec);
  return rec;
}
const lblP     = L('<b>P</b>', 'fade', { fontSize: '22px', offset: [0, -26] });
const lblp1    = L('<b>p</b><sub>1</sub>', 'fade', { fontSize: '20px', offset: [-22, 24] });
const lblp2    = L('<b>p</b><sub>2</sub>', 'keep', { fontSize: '20px', offset: [24, 26] });
const lblO1    = L('O<sub>1</sub>', 'fade', { fontSize: '20px', offset: [-6, 32] });
const lblO2    = L('O<sub>2</sub>', 'ghost', { fontSize: '20px', offset: [8, 32] });
const lble1    = L('e<sub>1</sub>', 'fade', { fontSize: '18px', offset: [4, 26] });
const lble2    = L('e<sub>2</sub>', 'keep', { fontSize: '18px', offset: [6, 26] });
const lblCam1  = L('Camera 1', 'fade', { fontSize: '19px' });
const lblCam2  = L('Camera 2', 'ghost', { fontSize: '19px' });
const lblPlane = L('Epipolar plane', 'fade', { fontSize: '20px' });
const lblLn1   = L('<span class="rot" style="display:inline-block">Epipolar line</span>', 'fade',
                   { fontSize: '15px', offset: [0, -13] });
const lblLn2   = L('<span class="rot" style="display:inline-block">Epipolar line</span>', 'keep',
                   { fontSize: '15px', offset: [0, -13] });

function updateLabels() {
  lblP.e.pos.copy(state.P);
  lblp1.e.pos.copy(P1);
  lblp2.e.pos.copy(P2);
  lblO1.e.pos.copy(O1);
  lblO2.e.pos.copy(O2);
  lble1.e.pos.copy(E1);
  lble2.e.pos.copy(E2);
  lblCam1.e.pos.copy(O1).add(new THREE.Vector3(-1.7 * U, 0.7 * U, 0));
  lblCam2.e.pos.copy(O2).add(new THREE.Vector3(1.7 * U, 1.0 * U, 0));
  lblPlane.e.pos.copy(O1).add(state.P).add(O2).multiplyScalar(1 / 3).addScaledVector(UP, 0.9 * U);
  lblLn1.e.pos.copy(line1A).lerp(line1B, 0.7);
  lblLn2.e.pos.copy(line2A).lerp(line2B, 0.7);
}
updateLabels();

/* ── hover / click explainers ────────────────────────────────────────────── */
registerInteractive(epiTri, {
