  { title: 'The rig and the baseline',
    narration: 'Two camera centres O₁ and O₂ are joined by the dashed baseline, which pierces each image plane at the epipoles e₁ and e₂. Everything else is built from these five points.',
    st: { view: '3D rig', baseline: 10, yaw: -12, sweep: false } },
  { title: 'One point, one plane',
    narration: 'The scene point P closes the triangle O₁–P–O₂: that yellow triangle is the epipolar plane, and the red rays O₁P and O₂P pierce the image planes at p₁ and p₂.',
    st: { view: '3D rig', baseline: 10, yaw: -12, sweep: false } },
  { title: 'Sweeping P about the baseline',
    narration: 'The epipolar plane rotates around the fixed baseline like a page in a book, so p₁ and p₂ slide but each stays on its epipolar line through its epipole. Drag P yourself to explore.',
    st: { view: '3D rig', baseline: 10, yaw: -12, sweep: true } },
  { title: 'Only relative pose matters',
    narration: 'Widen the baseline and rotate camera 2. The epipoles migrate and the epipolar lines fan to new orientations — the constraint is set by camera geometry alone.',
    st: { view: '3D rig', baseline: 13, yaw: 28, sweep: false } },
  { title: '2D search becomes 1D',
    narration: 'Looking straight into camera 2\'s image, the match for p₁ must lie on a single red line — which is why stereo matching is a one-dimensional search.',
    st: { view: 'Camera 2 image', baseline: 10, yaw: -12, sweep: false } }
];
let step = 0;
function goToStep(i) {
  step = (i % STEPS.length + STEPS.length) % STEPS.length;
  const s = STEPS[step];
  tgtBase = s.st.baseline;
  tgtYaw = s.st.yaw;
  setView(s.st.view);
  if (s.st.sweep) { state.P.copy(P_DEFAULT); setSweep(true); } else setSweep(false);
  stepTitle.textContent = (step + 1) + '/' + STEPS.length + '. ' + s.title;
  stepText.textContent = s.narration;
}
bPrev.addEventListener('click', () => goToStep(step - 1));
bNext.addEventListener('click', () => goToStep(step + 1));
goToStep(0);

/* ── drag P ──────────────────────────────────────────────────────────────── */
const rc = new THREE.Raycaster();
const dragPlane = new THREE.Plane();
const hitPt = new THREE.Vector3();
let dragging = false;

function ptrNDC(ev) {
  const r = dom.getBoundingClientRect();
  return new THREE.Vector2(
    ((ev.clientX - r.left) / r.width) * 2 - 1,
    -((ev.clientY - r.top) / r.height) * 2 + 1
  );
}
dom.addEventListener('pointerdown', (ev) => {
  rc.setFromCamera(ptrNDC(ev), camera);
  if (rc.intersectObject(pDot, true).length) {
    dragging = true;
    setSweep(false);
    controls.enabled = false;
    if (dom.setPointerCapture) { try { dom.setPointerCapture(ev.pointerId); } catch (e) {} }
  }
});
dom.addEventListener('pointermove', (ev) => {
  if (!dragging) {
    rc.setFromCamera(ptrNDC(ev), camera);
    if (rc.intersectObject(pDot, true).length) dom.style.cursor = 'move';
    return;
  }
  const n = ev.shiftKey ? UP.clone() : camera.getWorldDirection(new THREE.Vector3()).negate();
  dragPlane.setFromNormalAndCoplanarPoint(n, state.P);
  rc.setFromCamera(ptrNDC(ev), camera);
  if (rc.ray.intersectPlane(dragPlane, hitPt)) {
    const half = state.baseline * U / 2;
    state.P.set(
      THREE.MathUtils.clamp(hitPt.x, -half * 0.95, half * 0.95),
      THREE.MathUtils.clamp(hitPt.y, 1.2 * U, 7.5 * U),
      THREE.MathUtils.clamp(hitPt.z, -5.0 * U, 4.0 * U)
    );
  }
});
window.addEventListener('pointerup', () => {
  if (dragging) { dragging = false; controls.enabled = true; dom.style.cursor = 'default'; }
});

/* ── per-frame: tweens, billboards, rotated labels, opacity fades ────────── */
const FADE = { keep: 1, ghost: 0.3, fade: 0.07 };
const _pa = new THREE.Vector3(), _pb = new THREE.Vector3();

function screenAngleDeg(a, b) {
  _pa.copy(a).project(camera); _pb.copy(b).project(camera);
  const dx = (_pb.x - _pa.x) * dom.clientWidth;
  const dy = -(_pb.y - _pa.y) * dom.clientHeight;
  let ang = Math.atan2(dy, dx) * 180 / Math.PI;
  if (ang > 90) ang -= 180;
  if (ang < -90) ang += 180;
  return ang;
}

function tick() {
  requestAnimationFrame(tick);

  if (Math.abs(tgtBase - state.baseline) > 0.005) state.baseline += (tgtBase - state.baseline) * 0.12;
  else state.baseline = tgtBase;
  if (Math.abs(tgtYaw - state.yaw) > 0.02) state.yaw += (tgtYaw - state.yaw) * 0.12;
  else state.yaw = tgtYaw;
  sBase.value = state.baseline.toFixed(1);
  sYaw.value = Math.round(state.yaw);
  vBase.textContent = state.baseline.toFixed(1);
  vYaw.textContent = Math.round(state.yaw);

  if (sweep) {
    sweepT += 0.012;
    const a = sweepA0 + 0.55 * Math.sin(sweepT);
    state.P.y = sweepR * Math.cos(a);
    state.P.z = sweepR * Math.sin(a);
    if (state.P.y < 1.2 * U) state.P.y = 1.2 * U;
  }

  update();
  updateLabels();

  for (const b of billboards) b.quaternion.copy(camera.quaternion);

  if (lblLn1.rot) lblLn1.rot.style.transform = 'rotate(' + screenAngleDeg(line1A, line1B).toFixed(1) + 'deg)';
  if (lblLn2.rot) lblLn2.rot.style.transform = 'rotate(' + screenAngleDeg(line2A, line2B).toFixed(1) + 'deg)';

  fadeMix += (fadeTarget - fadeMix) * 0.09;
  for (const m of mats) {
    const lvl = (FADE[m.userData.role] !== undefined) ? FADE[m.userData.role] : FADE.fade;
    m.opacity = m.userData.base * (1 + (lvl - 1) * fadeMix);
  }
  for (const r of labelRefs) {
    const lvl = (FADE[r.role] !== undefined) ? FADE[r.role] : FADE.fade;
    r.e.div.style.opacity = (1 + (lvl - 1) * fadeMix).toFixed(3);
  }

  if (camAnim && !dragging) {
    if (state.view === '3D rig') {
      camGoalPos.copy(homePos);
      camGoalLook.copy(homeTarget);
    } else {
      camGoalPos.copy(O2).addScaledVector(f2, -CAM2_DIST);
      camGoalLook.copy(F2.C);
    }
    camera.position.lerp(camGoalPos, 0.1);
    controls.target.lerp(camGoalLook, 0.1);
    camera.up.set(0, 1, 0);
    controls.update();
    if (camera.position.distanceTo(camGoalPos) < 0.006) camAnim = false;
  }
}
tick();
